// Normalise the HubSpot payload into the PRD 20 lead intake event.
// tenant_ref is deliberately NOT sent: PRD 8.2 requires the platform to
// derive the tenant from the service credential, never from the caller.
const body = $json.body ?? $json;
const props = body.properties ?? {};

// Consent is collected upstream at the landing page or Meta lead form, so
// pass through whatever HubSpot holds about it. If none of these are set the
// platform records the campaign's declared origin instead - it never blocks
// on this, it just prefers the more specific record when one exists.
const consentBasis =
  props.consent_basis ??
  (props.hs_legal_basis ? 'opt_in_form' : null) ??
  (props.hs_marketable_status === 'true' ? 'opt_in_form' : null);

const consentSource =
  props.consent_source ??
  props.hs_analytics_source ??
  (props.hs_latest_source === 'PAID_SOCIAL' ? 'meta_lead_form' : null) ??
  'hubspot';

return {
  json: {
    event_id: body.eventId ?? body.objectId ?? $execution.id,
    source: 'hubspot',
    record_id: String(body.objectId ?? props.hs_object_id ?? ''),
    campaign_ref: $vars.CAMPAIGN_ID,
    contact: {
      name: [props.firstname, props.lastname].filter(Boolean).join(' ') || null,
      phone: props.phone ?? props.mobilephone ?? null,
      email: props.email ?? null
    },
    consent: consentBasis
      ? {
          basis: consentBasis,
          source: consentSource,
          evidence_ref: props.consent_evidence_ref ?? props.hs_object_id ?? null,
          captured_at: props.consent_captured_at ?? props.createdate ?? null
        }
      : null,
    correlation_id: $execution.id
  }
};
